const math = require('mathjs');

const generate = () => {
  const unitSystems = [
    {
      system: "uscs",
      speedUnit: "mph",
      timeUnit: "hours",
      distUnit: "miles",
      speedMin: 60,
      speedMax: 121,
      timeMin: 2,
      timeMax: 9
    },
    {
      system: "si",
      speedUnit: "km/h",
      timeUnit: "hours",
      distUnit: "km",
      speedMin: 90,
      speedMax: 181,
      timeMin: 2,
      timeMax: 9
    }
  ];

  const selectedSystem = unitSystems[math.randomInt(0, unitSystems.length)];
  const speed = math.randomInt(selectedSystem.speedMin, selectedSystem.speedMax);
  const time = math.randomInt(selectedSystem.timeMin, selectedSystem.timeMax);
  const distance = speed * time;

  const data = {
    params: {
      speed: speed,
      time: time,
      unitsSpeed: selectedSystem.speedUnit,
      unitsTime: selectedSystem.timeUnit,
      unitsDist: selectedSystem.distUnit
    },
    correct_answers: {
      distance: distance
    },
    nDigits: 2,
    sigfigs: 2
  };

  return data;
};

module.exports = {
  generate
};

